(function(){'use strict';let busy=false;async function check(){if(busy)return;busy=true;try{const r=await fetch('/api/device/session',{headers:{'X-Desk-Preview':'1'},cache:'no-store',credentials:'same-origin'});if(r.status===401||r.status===403||r.status===404)location.replace('/');}catch{}finally{busy=false}}check();setInterval(check,15000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)check()});})();
